import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Object3D, Color } from 'three/webgpu';
import { texture, uv, vec4, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Object3D();
  group.name = 'hub-features-card-1-label';
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.8;
  const height = 1.1;

  const geometry = new PlaneGeometry(width, height, 1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader('/prism-mock/home/nodes/orb-decor.png');

  const inkColor = new Color('#16161d');
  const surfaceColor = new Color('#0b0b10');

  const vUv = uv();
  const gradient = mix(vec4(surfaceColor, 1.0), vec4(inkColor, 1.0), vUv.y);

  if (map) {
    const tex = texture(map, vUv);
    material.colorNode = mix(gradient, tex, tex.a);
  } else {
    material.colorNode = gradient;
  }

  const mesh = new Mesh(geometry, material);
  mesh.name = 'features-card-1-label-plane';
  group.add(mesh);

  const textMeshes = [];
  const textContent = config.textContent || [];

  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    textContent.forEach((entry, i) => {
      const textMesh = ctx.fontAtlas.createText({
        text: entry.text,
        font: entry.role === 'headline' ? 'Lora' : 'JetBrains Mono',
        weight: entry.weight || 400,
        sizeEm: entry.role === 'headline' ? 0.34 : 0.13,
        color: '#e8ecf2',
        align: 'center',
        anchor: 'middle',
        atlasIndex: 0,
        sourceRect: [0, 0, 512, 320],
      });
      if (textMesh) {
        textMesh.position.set(0, -i * 0.05, 0.01);
        group.add(textMesh);
        textMeshes.push(textMesh);
      }
    });
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    textMeshes.forEach((textMesh) => {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
      group.remove(textMesh);
    });
    group.remove(mesh);
  };

  return group;
}
